M(T7,"El principio de prevención enfrenta un riesgo:","Cierto y previsible",["Incierto por falta de certeza científica","Solo de carácter nuclear","Exclusivamente marino"],"La precaución es la que enfrenta el riesgo incierto.",X,1,["confusables"])
M(T7,"¿Cuál NO es un elemento de la precaución según Mollar?","La certeza científica sobre el daño",["La incertidumbre científica","El riesgo de daño","Un daño grave e irreversible"],"Justamente la falta de certeza es su rasgo distintivo.",X,2,["confusables"])
M(T7,"En Gabčíkovo-Nagymaros, la CIJ, respecto de la precaución:","No la reconoció como principio general por dudar de la opinio iuris",["La declaró costumbre universal","La aplicó invirtiendo la carga de la prueba","La consideró parte del jus cogens"],"La inversión de la carga la propuso Weeramantry en disidencia (1995).",X,2,["confusables"])
